from pathlib import Path
import sys,json,hashlib,numpy as np,trimesh,cadquery as cq
from OCP.gp import gp_Trsf
W=Path(__file__).parent;out=W/'controles_independientes';out.mkdir(exist_ok=True);entries=json.loads((W/'ENTRADAS_SHA256.json').read_text());specs=[]
def source(shape,name):
 directory=out/name;directory.mkdir(exist_ok=True);V,F=shape.copy().tessellate(.0005,angularTolerance=.03);mesh=trimesh.Trimesh([p.toTuple()for p in V],F,process=True);path=directory/'entrada.stl';path.write_bytes(mesh.export(file_type='stl'));cq.exporters.export(shape,str(directory/'referencia_CAD.step'));return path
body=trimesh.load(entries['body_stl']['path'],force='mesh',process=True);R=trimesh.transformations.rotation_matrix(.47,[1,2,3]);R[:3,3]=np.array([7.,-4.,2.])-R[:3,:3]@body.bounds.mean(0);body.apply_transform(R);directory=out/'body_girada';directory.mkdir(exist_ok=True);path=directory/'entrada_anonima.stl';path.write_bytes(body.export(file_type='stl'));specs.append(dict(id='Body_girada_anonima',source=str(path),perfil='precision',expect_r17=True,transformacion=R.tolist()))
specs.append(dict(id='Body_impresion',source=entries['body_stl']['path'],perfil='impresion',expect_r17=True))
bush=cq.Solid.makeCylinder(4,3).fuse(cq.Solid.makeCylinder(6,10,cq.Vector(0,0,3))).fuse(cq.Solid.makeCylinder(4,2,cq.Vector(0,0,13))).cut(cq.Solid.makeCylinder(2,15)).clean();path=source(bush,'casquillo_escalonado');specs.append(dict(id='Independiente_casquillo',source=str(path),perfil='precision',expect_r17=True,modelo='CAD independiente generado, dos cambios de diámetro y taladro pasante'))
shape=cq.Solid.makeCylinder(5,8).cut(cq.Solid.makeCylinder(2,8)).cut(cq.Solid.makeBox(.6,1.,.1,cq.Vector(3.,-.5,0))).clean();T=trimesh.transformations.rotation_matrix(.42,[1,-2,3]);T[:3,3]=[-12,6,4];tr=gp_Trsf();tr.SetValues(*map(float,T[:3].ravel()));shape=shape.transformShape(cq.Matrix(tr));path=source(shape,'casquillo_rebaje_oblicuo');specs.append(dict(id='Independiente_rebaje_oblicuo',source=str(path),perfil='precision',expect_r17=True,modelo='CAD independiente generado, rebaje de 0,1 mm y orientación oblicua'))
for s in specs:s['sha256']=hashlib.sha256(Path(s['source']).read_bytes()).hexdigest()
(W/'CONTROLES_ADICIONALES.json').write_text(json.dumps(specs,ensure_ascii=False,indent=2));print(json.dumps([{k:v for k,v in s.items()if k in ['id','source','perfil','sha256']}for s in specs],ensure_ascii=False,indent=2))
